import { writeFile } from 'node:fs/promises'
import { resolve } from 'node:path'
import { type Command, type CommandContext, EXIT } from '../framework'
import { resolveTarget } from '../target'

/** A union of string literals; keys come from the server, so JSON.stringify quotes them safely. */
function union(values: readonly string[]): string {
  return values.length === 0 ? 'never' : values.map((v) => JSON.stringify(v)).join(' | ')
}

/**
 * The text of the generated file for a set of roles.
 *
 * @param roles - Every role of the environment, built-ins included.
 * @returns TypeScript source: `TulaPermission`, `TulaRole` and `TULA_PERMISSIONS`.
 */
export function renderTypes(roles: readonly { key: string; permissions: readonly string[] }[]) {
  const permissions = [...new Set(roles.flatMap((role) => role.permissions))].sort()
  const keys = [...new Set(roles.map((role) => role.key))].sort()
  return `// Generated by \`tula types\`. Do not edit: run it again after a role changes.

export type TulaPermission = ${union(permissions)}

export type TulaRole = ${union(keys)}

export const TULA_PERMISSIONS = [${permissions.map((p) => JSON.stringify(p)).join(', ')}] as const
`
}

async function run(context: CommandContext): Promise<number> {
  const { flags, io, output } = context
  const name = typeof flags.env === 'string' ? flags.env : 'default'
  const target = await resolveTarget({ name, environment: {}, flags, io, output })
  const { data } = await target.admin.call('listOrganizationRoles', {})
  const path = resolve(io.cwd, typeof flags.out === 'string' ? flags.out : 'tula-types.gen.ts')
  await writeFile(path, renderTypes(data.data))
  output.error(`Wrote ${path}`)
  return EXIT.ok
}

/**
 * `tula types`: write the environment's permission keys as a TypeScript union, so a
 * misspelled key fails to compile.
 *
 * @example
 * ```sh
 * tula types --out src/tula-types.gen.ts
 * ```
 */
export const typesCommand: Command = {
  name: 'types',
  summary: 'Write the environment’s permission keys as TypeScript types.',
  usage: 'tula types [--out <path>] [--env <name>]',
  description:
    'Reads every role of the environment (the built-in ones too) and writes the distinct ' +
    'permission keys as `TulaPermission`, the role keys as `TulaRole` and the keys as the ' +
    'constant `TULA_PERMISSIONS`. Run it again after a role changes. Needs a secret key.',
  options: {
    out: {
      type: 'string',
      value: '<path>',
      description: 'Where to write. Default tula-types.gen.ts.',
    },
    env: {
      type: 'string',
      short: 'e',
      value: '<name>',
      description: 'Read TULA_SECRET_KEY_<NAME> first.',
    },
    'api-url': { type: 'string', value: '<url>', description: 'The Tula API.' },
    'insecure-http': { type: 'boolean', description: 'Allow plain http that is not localhost.' },
    'secret-key-file': {
      type: 'string',
      value: '<path>',
      description: 'Read the secret key from a file.',
    },
  },
  run,
}
